### What problem does this feature solve?

表格跨页分割问题处理，表格光标问题还有待解决

### What does the proposed API look like?

Draw.ts中表格分割方法处理  
public computeRowList(payload: IComputeRowListPayload) {
    const {
      innerWidth,
      elementList,
      isPagingMode = false,
      isFromTable = false,
      startX = 0,
      startY = 0,
      pageHeight = 0,
      mainOuterHeight = 0,
      surroundElementList = []
    } = payload
    const {
      defaultSize,
      defaultRowMargin,
      scale,
      table: { tdPadding,defaultTrMinHeight },
      defaultTabWidth
    } = this.options
    const defaultBasicRowMarginHeight = this.getDefaultBasicRowMarginHeight()
    const canvas = document.createElement('canvas')
    const ctx = canvas.getContext('2d') as CanvasRenderingContext2D
    // 计算列表偏移宽度
    const listStyleMap = this.listParticle.computeListStyle(ctx, elementList)
    const rowList: IRow[] = []
    if (elementList.length) {
      rowList.push({
        width: 0,
        height: 0,
        ascent: 0,
        elementList: [],
        startIndex: 0,
        rowIndex: 0,
        rowFlex: elementList?.[0]?.rowFlex || elementList?.[1]?.rowFlex
      })
    }
    // 起始位置及页码计算
    let x = startX
    let y = startY
    let pageNo = 0
    // 列表位置
    let listId: string | undefined
    let listIndex = 0
    // 控件最小宽度
    let controlRealWidth = 0
    for (let i = 0; i < elementList.length; i++) {
      const curRow: IRow = rowList[rowList.length - 1]
      let element = elementList[i]
      const rowMargin =
        defaultBasicRowMarginHeight * (element.rowMargin ?? defaultRowMargin)
      const metrics: IElementMetrics = {
        width: 0,
        height: 0,
        boundingBoxAscent: 0,
        boundingBoxDescent: 0
      }
      // 实际可用宽度
      const offsetX =
        curRow.offsetX ||
        (element.listId && listStyleMap.get(element.listId)) ||
        0
      const availableWidth = innerWidth - offsetX
      // 增加起始位置坐标偏移量
      const isStartElement = curRow.elementList.length === 1
      x += isStartElement ? offsetX : 0
      y += isStartElement ? curRow.offsetY || 0 : 0
      if (
        (element.hide || element.control?.hide || element.area?.hide) &&
        !this.isDesignMode()
      ) {
        const preElement = curRow.elementList[curRow.elementList.length - 1]
        metrics.height =
          preElement?.metrics.height || this.options.defaultSize * scale
        metrics.boundingBoxAscent = preElement?.metrics.boundingBoxAscent || 0
        metrics.boundingBoxDescent = preElement?.metrics.boundingBoxDescent || 0
      } else if (
        element.type === ElementType.IMAGE ||
        element.type === ElementType.LATEX
      ) {
        // 浮动图片无需计算数据
        if (
          element.imgDisplay === ImageDisplay.SURROUND ||
          element.imgDisplay === ImageDisplay.FLOAT_TOP ||
          element.imgDisplay === ImageDisplay.FLOAT_BOTTOM
        ) {
          metrics.width = 0
          metrics.height = 0
          metrics.boundingBoxDescent = 0
        } else {
          const elementWidth = element.width! * scale
          const elementHeight = element.height! * scale
          // 图片超出尺寸后自适应（图片大小大于可用宽度时）
          if (elementWidth > availableWidth) {
            const adaptiveHeight =
              (elementHeight * availableWidth) / elementWidth
            element.width = availableWidth / scale
            element.height = adaptiveHeight / scale
            metrics.width = availableWidth
            metrics.height = adaptiveHeight
            metrics.boundingBoxDescent = adaptiveHeight
          } else {
            metrics.width = elementWidth
            metrics.height = elementHeight
            metrics.boundingBoxDescent = elementHeight
          }
        }
        metrics.boundingBoxAscent = 0
      } else if (element.type === ElementType.TABLE) {

        const tdPaddingWidth = tdPadding[1] + tdPadding[3]
        const tdPaddingHeight = tdPadding[0] + tdPadding[2]

        // 表格分页处理进度：https://github.com/Hufe921/canvas-editor/issues/41
        // 查看后续表格是否属于同一个源表格-存在即合并
        if (element.pagingId && element.pagingIndex === 0) {
          let tableIndex = i + 1
          let combineCount = 0
          const allTrList = [...element.trList!]
          while (tableIndex < elementList.length) {
            const nextElement = elementList[tableIndex]
            if (nextElement.pagingId === element.pagingId) {
              const nexTrList = nextElement.trList!.filter(
                tr => !tr.pagingRepeat
              )
              allTrList.push(...nexTrList)
              element.height! += nextElement.height!
              tableIndex++
              combineCount++
            } else {
              break
            }
          }

          if (combineCount) {
            const trMap = new Map<number, any[]>()

            allTrList.forEach(tr => {
              const originalRowIndex = tr.originalRowIndex
              if (originalRowIndex !== undefined) {
                if (!trMap.has(originalRowIndex)) {
                  trMap.set(originalRowIndex, [])
                }
                trMap.get(originalRowIndex)!.push(tr)
              }
            })

            const mergedTrList: any[] = []

            trMap.forEach(trs => {
              if (trs.length === 1) {
                mergedTrList.push(trs[0])
              } else {
                const baseTr = trs[0]
                const mergedTr = deepClone(baseTr)

                baseTr.tdList.forEach((_baseTd: any, tdIndex: number) => {
                  const mergedTd = mergedTr.tdList[tdIndex]
                  mergedTd.value = []

                  trs.forEach(tr => {
                    const td = tr.tdList[tdIndex]
                    if (td && td.value) {
                      mergedTd.value.push(...td.value)
                    }
                  })
                })

                mergedTrList.push(mergedTr)
              }
            })

            mergedTrList.sort((a, b) => {
              const aIndex = a.originalRowIndex ?? 0
              const bIndex = b.originalRowIndex ?? 0
              return aIndex - bIndex
            })

            element.trList = mergedTrList
            elementList.splice(i + 1, combineCount)
          }
        }

        // 处理表格行
        const { tableWidth, tableHeight } = this.handleTrList(element, {
          isPagingMode,
          tdPaddingWidth,
          tdPaddingHeight
        })

        element.width = tableWidth
        element.height = tableHeight
        const elementWidth = tableWidth * scale
        const elementHeight = tableHeight * scale
        metrics.width = elementWidth
        metrics.height = elementHeight
        metrics.boundingBoxDescent = elementHeight
        metrics.boundingBoxAscent = -rowMargin
        // 后一个元素也是表格则移除行间距
        if (elementList[i + 1]?.type === ElementType.TABLE) {
          metrics.boundingBoxAscent -= rowMargin
        }
        // 表格分页处理(拆分表格)
        if (isPagingMode) {
          // 表格分页处理(拆分表格)
          const mainHeight = this.getMainHeight() * scale // 表格主高度
          let curPagePreHeight = 0
          // 计算前面元素高度
          for (let r = 0; r < rowList.length; r++) {
            const row = rowList[r]
            const rowOffsetY = row.offsetY || 0
            curPagePreHeight += row.height + rowOffsetY
          }
          // 求出最后一页的剩余高度
          let lastPageRemainHeight =
            mainHeight - ((curPagePreHeight * scale) % mainHeight)

          // 表格分页处理-如果当前表格不是第一页，则需要将表格高度设置为分页高度
          if (element.pagingIndex && element.pagingIndex !== 0) {
            lastPageRemainHeight = mainHeight
          }

          // 判断当前表格是否可以被剩下的高度容下
          if (elementHeight > lastPageRemainHeight) {
            console.log('tdPaddingHeight',tdPaddingHeight)
            console.log('rowMargin', rowMargin)

            const splitTableList = this.splitTable(
              element,
              lastPageRemainHeight - defaultTrMinHeight * scale,
              mainHeight,
              {
                isPagingMode,
                tdPaddingWidth,
                tdPaddingHeight,
                scale
              }
            )

            element = elementList[i] = splitTableList[0]
            metrics.height = splitTableList[0].height * scale
            metrics.boundingBoxDescent = metrics.height
            metrics.boundingBoxAscent = -rowMargin

            this.spliceElementList(
              elementList,
              i + 1,
              0,
              splitTableList.filter(t => t.pagingIndex !== 0)
            )
          }

          // 表格经过分页处理-需要处理上下文
          if (element.pagingId) {
            // 获取当前的光标位置上下文
            const positionContext = this.position.getPositionContext()

            // 表格经过分页处理后，需要更新光标位置上下文
            if (positionContext.isTable) {
              // 查找光标所在表格索引（根据trId搜索）

              // 从当前元素位置开始向后搜索
              let tableIndex = i
              while (tableIndex < elementList.length) {
                const curElement = elementList[tableIndex]

                // 在当前表格片段中查找光标所在的行（通过trId匹配）
                if (curElement.pagingId !== element.pagingId) break
                if (curElement.id === positionContext.tableId) {
                  // 查找光标所在行索引（通过trIndex匹配）
                  const trIndex = curElement.trList!.findIndex(
                    r => r.originalRowIndex === positionContext.trIndex
                  )
                  if (~trIndex) {
                    // 查找光标所在单元格索引（通过tdId匹配）
                    if (
                      positionContext.tdValueIndex ===
                      curElement.trList![trIndex].tdList![
                        positionContext.tdIndex!
                        ]!.value.length -
                      1
                    ) {

                      const newElement = elementList[tableIndex + 1]
                      console.log('newElement',newElement)
                      positionContext.index = tableIndex + 1
                      positionContext.trIndex = 0
                      positionContext.tdValueIndex = 0
                      positionContext.tableId = newElement.id
                      positionContext.tdId =
                        newElement.trList![0].tdList![
                          positionContext.tdIndex!
                          ].id
                      positionContext.trId = newElement.trList![0].id
                      // 设置页面新位置
                      this.position.setPositionContext(positionContext)
                      // 等待DOM更新完成后，设置光标位置为0
                      nextTick(() => {
                        this.setCursor(0)
                      })
                      break
                    }
                  }
                }
                // 继续搜索下一个表格片段
                tableIndex++
              }
            }
          }
        }

      } else if (element.type === ElementType.SEPARATOR) {
        const {
          separator: { lineWidth }
        } = this.options
        element.width = availableWidth / scale
        metrics.width = availableWidth
        metrics.height = lineWidth * scale
        metrics.boundingBoxAscent = -rowMargin
        metrics.boundingBoxDescent = -rowMargin + metrics.height
      } else if (element.type === ElementType.PAGE_BREAK) {
        element.width = availableWidth / scale
        metrics.width = availableWidth
        metrics.height = defaultSize
      } else if (
        element.type === ElementType.RADIO ||
        element.controlComponent === ControlComponent.RADIO
      ) {
        const { width, height, gap } = this.options.radio
        const elementWidth = width + gap * 2
        element.width = elementWidth
        metrics.width = elementWidth * scale
        metrics.height = height * scale
      } else if (
        element.type === ElementType.CHECKBOX ||
        element.controlComponent === ControlComponent.CHECKBOX
      ) {
        const { width, height, gap } = this.options.checkbox
        const elementWidth = width + gap * 2
        element.width = elementWidth
        metrics.width = elementWidth * scale
        metrics.height = height * scale
      } else if (element.type === ElementType.TAB) {
        metrics.width = defaultTabWidth * scale
        metrics.height = defaultSize * scale
        metrics.boundingBoxDescent = 0
        metrics.boundingBoxAscent = metrics.height
      } else if (element.type === ElementType.BLOCK) {
        if (!element.width) {
          metrics.width = availableWidth
        } else {
          const elementWidth = element.width * scale
          metrics.width = Math.min(elementWidth, availableWidth)
        }
        metrics.height = element.height! * scale
        metrics.boundingBoxDescent = metrics.height
        metrics.boundingBoxAscent = 0
      } else {
        // 设置上下标真实字体尺寸
        const size = element.size || defaultSize
        if (
          element.type === ElementType.SUPERSCRIPT ||
          element.type === ElementType.SUBSCRIPT
        ) {
          element.actualSize = Math.ceil(size * 0.6)
        }
        metrics.height = (element.actualSize || size) * scale
        ctx.font = this.getElementFont(element)
        const fontMetrics = this.textParticle.measureText(ctx, element)
        metrics.width = fontMetrics.width * scale
        if (element.letterSpacing) {
          metrics.width += element.letterSpacing * scale
        }
        metrics.boundingBoxAscent =
          (element.value === ZERO
            ? element.size || defaultSize
            : fontMetrics.actualBoundingBoxAscent) * scale
        metrics.boundingBoxDescent =
          fontMetrics.actualBoundingBoxDescent * scale
        if (element.type === ElementType.SUPERSCRIPT) {
          metrics.boundingBoxAscent += metrics.height / 2
        } else if (element.type === ElementType.SUBSCRIPT) {
          metrics.boundingBoxDescent += metrics.height / 2
        }
      }
      const ascent =
        !element.hide &&
        ((element.imgDisplay !== ImageDisplay.INLINE &&
          element.type === ElementType.IMAGE) ||
          element.type === ElementType.LATEX)
          ? metrics.height + rowMargin
          : metrics.boundingBoxAscent + rowMargin
      const height =
        rowMargin +
        metrics.boundingBoxAscent +
        metrics.boundingBoxDescent +
        rowMargin
      const rowElement: IRowElement = Object.assign(element, {
        metrics,
        left: 0,
        style: this.getElementFont(element, scale)
      })
      // 暂时只考虑非换行场景：控件开始时统计宽度，结束时消费宽度及还原
      if (rowElement.control?.minWidth) {
        if (rowElement.controlComponent) {
          controlRealWidth += metrics.width
        }
        if (rowElement.controlComponent === ControlComponent.POSTFIX) {
          // 设置最小宽度控件属性（字符偏移量）
          this.control.setMinWidthControlInfo({
            row: curRow,
            rowElement,
            availableWidth,
            controlRealWidth
          })
          controlRealWidth = 0
        }
      }
      // 超过限定宽度
      const preElement = elementList[i - 1]
      let nextElement = elementList[i + 1]
      // 累计行宽 + 当前元素宽度 + 排版宽度(英文单词整体宽度 + 后面标点符号宽度)
      let curRowWidth = curRow.width + metrics.width
      if (this.options.wordBreak === WordBreak.BREAK_WORD) {
        if (
          (!preElement?.type || preElement?.type === ElementType.TEXT) &&
          (!element.type || element.type === ElementType.TEXT)
        ) {
          // 英文单词
          const word = `${preElement?.value || ''}${element.value}`
          if (this.WORD_LIKE_REG.test(word)) {
            const { width, endElement } = this.textParticle.measureWord(
              ctx,
              elementList,
              i
            )
            // 单词宽度大于行可用宽度，无需折行
            const wordWidth = width * scale
            if (wordWidth <= availableWidth) {
              curRowWidth += wordWidth
              nextElement = endElement
            }
          }
          // 标点符号
          const punctuationWidth = this.textParticle.measurePunctuationWidth(
            ctx,
            nextElement
          )
          curRowWidth += punctuationWidth * scale
        }
      }
      // 列表信息
      if (element.listId) {
        if (element.listId !== listId) {
          listIndex = 0
        } else if (element.value === ZERO && !element.listWrap) {
          listIndex++
        }
      }
      listId = element.listId
      // 计算四周环绕导致的元素偏移量
      const surroundPosition = this.position.setSurroundPosition({
        pageNo,
        rowElement,
        row: curRow,
        rowElementRect: {
          x,
          y,
          height,
          width: metrics.width
        },
        availableWidth,
        surroundElementList
      })
      x = surroundPosition.x
      curRowWidth += surroundPosition.rowIncreaseWidth
      x += metrics.width
      // 是否强制换行
      const isForceBreak =
        element.type === ElementType.SEPARATOR ||
        element.type === ElementType.TABLE ||
        preElement?.type === ElementType.TABLE ||
        preElement?.type === ElementType.BLOCK ||
        element.type === ElementType.BLOCK ||
        preElement?.imgDisplay === ImageDisplay.INLINE ||
        element.imgDisplay === ImageDisplay.INLINE ||
        preElement?.listId !== element.listId ||
        (preElement?.areaId !== element.areaId && !element.area?.hide) ||
        (element.control?.flexDirection === FlexDirection.COLUMN &&
          (element.controlComponent === ControlComponent.CHECKBOX ||
            element.controlComponent === ControlComponent.RADIO) &&
          preElement?.controlComponent === ControlComponent.VALUE) ||
        (i !== 0 && element.value === ZERO && !element.area?.hide)
      // 是否宽度不足导致换行
      const isWidthNotEnough = curRowWidth > availableWidth
      const isWrap = isForceBreak || isWidthNotEnough
      // 新行数据处理
      if (isWrap) {
        const row: IRow = {
          width: metrics.width,
          height,
          startIndex: i,
          elementList: [rowElement],
          ascent,
          rowIndex: curRow.rowIndex + 1,
          rowFlex: elementList[i]?.rowFlex || elementList[i + 1]?.rowFlex,
          isPageBreak: element.type === ElementType.PAGE_BREAK
        }
        // 控件缩进
        if (
          rowElement.controlComponent !== ControlComponent.PREFIX &&
          rowElement.control?.indentation === ControlIndentation.VALUE_START
        ) {
          // 查找到非前缀的第一个元素位置
          const preStartIndex = curRow.elementList.findIndex(
            el =>
              el.controlId === rowElement.controlId &&
              el.controlComponent !== ControlComponent.PREFIX
          )
          if (~preStartIndex) {
            const preRowPositionList = this.position.computeRowPosition({
              row: curRow,
              innerWidth: this.getInnerWidth()
            })
            const valueStartPosition = preRowPositionList[preStartIndex]
            if (valueStartPosition) {
              row.offsetX = valueStartPosition.coordinate.leftTop[0]
            }
          }
        }
        // 列表缩进
        if (element.listId) {
          row.isList = true
          row.offsetX = listStyleMap.get(element.listId!)
          row.listIndex = listIndex
        }
        // Y轴偏移量
        row.offsetY =
          !isFromTable &&
          element.area?.top &&
          element.areaId !== elementList[i - 1]?.areaId
            ? element.area.top * scale
            : 0
        rowList.push(row)
      } else {
        curRow.width += metrics.width
        // 减小块元素前第一行空行行高
        if (
          i === 0 &&
          (getIsBlockElement(elementList[1]) || !!elementList[1]?.areaId)
        ) {
          curRow.height = defaultBasicRowMarginHeight
          curRow.ascent = defaultBasicRowMarginHeight
        } else if (curRow.height < height) {
          curRow.height = height
          curRow.ascent = ascent
        }
        curRow.elementList.push(rowElement)
      }
      // 行结束时逻辑
      if (isWrap || i === elementList.length - 1) {
        // 换行原因：宽度不足
        curRow.isWidthNotEnough = isWidthNotEnough && !isForceBreak
        // 两端对齐、分散对齐
        if (
          !curRow.isSurround &&
          (preElement?.rowFlex === RowFlex.JUSTIFY ||
            (preElement?.rowFlex === RowFlex.ALIGNMENT &&
              curRow.isWidthNotEnough))
        ) {
          // 忽略换行符及尾部元素间隔设置
          const rowElementList =
            curRow.elementList[0]?.value === ZERO
              ? curRow.elementList.slice(1)
              : curRow.elementList
          const gap =
            (availableWidth - curRow.width) / (rowElementList.length - 1)
          for (let e = 0; e < rowElementList.length - 1; e++) {
            const el = rowElementList[e]
            el.metrics.width += gap
          }
          curRow.width = availableWidth
        }
      }
      // 重新计算坐标、页码、下一行首行元素环绕交叉
      if (isWrap) {
        x = startX
        y += curRow.height
        if (
          isPagingMode &&
          !isFromTable &&
          pageHeight &&
          (y - startY + mainOuterHeight + height > pageHeight ||
            element.type === ElementType.PAGE_BREAK)
        ) {
          y = startY
          // 删除多余四周环绕型元素
          deleteSurroundElementList(surroundElementList, pageNo)
          pageNo += 1
        }
        // 计算下一行第一个元素是否存在环绕交叉
        rowElement.left = 0
        const nextRow = rowList[rowList.length - 1]
        const surroundPosition = this.position.setSurroundPosition({
          pageNo,
          rowElement,
          row: nextRow,
          rowElementRect: {
            x,
            y,
            height,
            width: metrics.width
          },
          availableWidth,
          surroundElementList
        })
        x = surroundPosition.x
        x += metrics.width
      }
    }
    return rowList
  }

  /**
   * 拆分表格
   * @param element 表格元素
   * @param remainHeight 第一个表格的可用高度
   * @param mainHeight 主体高度
   * @param option 配置
   */
  private splitTable(
    element: IElement,
    remainHeight: number,
    mainHeight: number,
    option: {
      isPagingMode: boolean
      tdPaddingWidth: number
      tdPaddingHeight: number
      scale: number
    }
  ) {
    const tableList: any[] = []
    const pagingId = element.pagingId || getUUID()

    // 当前处理到那个
    let trIndex = 0
    // tdList拆分索引
    const tdSpliceIndexMap: any = {}

    // 循环创建表格，直到所有行都处理完毕
    let tableIndex = 0
    while (trIndex < element.trList!.length) {
      const table: any = {
        ...element,
        trList: [],
        id: tableIndex === 0 ? element.id! : getUUID(),
        pagingId,
        pagingIndex: tableIndex
      }

      // 当前页面剩余高度
      let remainingHeight = tableIndex === 0 ? remainHeight : mainHeight

      for (let r = trIndex; r < element.trList!.length; r++) {
        const tr = element.trList![r]
        // 初始化td拆分索引
        if (!tdSpliceIndexMap[r]) {
          tdSpliceIndexMap[r] = {}
        }
        // 计算当前行的最大高度
        const tdMaxHeight =
          Math.max(...tr.tdList.map(td => td.height || 0)) || 0

        // 判断当前行高度是否满足直接添加入表格，且当行并未拆分过
        if (
          tdSpliceIndexMap[r] &&
          Object.keys(tdSpliceIndexMap[r]).length <= 0 &&
          tdMaxHeight * option.scale <= remainingHeight
        ) {
          // 直接添加
          const cloneTr = deepClone(tr)
          cloneTr.originalRowIndex = r
          table.trList.push(cloneTr)
          remainingHeight -= tdMaxHeight * option.scale
          // 更新处理到那个tr
          trIndex = r + 1
        } else {
          const cloneTr = deepClone(tr)
          cloneTr.id = getUUID()
          cloneTr.tdList = []
          cloneTr.originalRowIndex = r
          let currentHeight = 0
          // 当前行是否全部循环完
          let endFor = true
          // 剩余高度不足，当前行拆分当前行
          tr.tdList.forEach((tdItem, tdItemIndex) => {
            // 拆分索引不存在，初始化
            if (!tdSpliceIndexMap[r][tdItemIndex]) {
              tdSpliceIndexMap[r][tdItemIndex] = 0
            }
            const cloneTd = deepClone(tdItem)
            cloneTd.id = getUUID()
            cloneTd.rowList = []
            cloneTd.value = []
            // 拆分索引大于等于当前行元素数量，添加换行符
            if (
              tdSpliceIndexMap[r][tdItemIndex] &&
              tdSpliceIndexMap[r][tdItemIndex] > tdItem.rowList!.length - 1
            ) {
              cloneTd.value = [
                {
                  value: '\n'
                }
              ]
            } else {
              let tdItemHeight = 0
              for (
                let z = tdSpliceIndexMap[r][tdItemIndex];
                z < tdItem.rowList!.length;
                z++
              ) {
                tdItemHeight += tdItem.rowList![z].height * option.scale || 0
                if (tdItemHeight > remainingHeight) {
                  // 超出当前页面剩余高度，标记为未完成
                  endFor = false
                  break
                } else {
                  cloneTd.value.push(
                    ...(tdItem.rowList![z].elementList?.map(item => ({
                      ...item,
                      trId: cloneTr.id,
                      tdId: cloneTd.id
                    })) || [])
                  )
                  tdSpliceIndexMap[r][tdItemIndex] = z + 1
                }
                currentHeight = Math.max(currentHeight, tdItemHeight)
              }
            }
            cloneTr.tdList.push(cloneTd)
          })

          // 当前行拆分完成，或当前行高度小于等于当前页面剩余高度
          if (currentHeight <= remainingHeight || endFor) {
            table.trList.push(cloneTr)
            remainingHeight -= currentHeight
            // 当前行拆分完成，更新处理到下一行
            if (endFor) {
              trIndex = r + 1
            }
          } else {
            // 当前表格已满，跳出循环
            break
          }
        }

        // 退出循环
        if (trIndex >= element.trList!.length || remainingHeight < 31) {
          break
        }
      }

      // 计算表格行数列数
      this.tableParticle.computeRowColInfo(table)
      // 计算表格宽度和高度
      const { tableWidth, tableHeight } = this.handleTrList(table, option)
      table.height = tableHeight
      table.width = tableWidth
      tableList.push(table)

      // 增加表格索引
      tableIndex++
    }

    return tableList
  }

  /**
   * 处理表格行
   * @param element 表格元素
   * @param trList 表格行列表
   * @param option 计算选项
   */
  private handleTrList(
    element: IElement,
    option: {
      isPagingMode: boolean
      tdPaddingWidth: number
      tdPaddingHeight: number
    }
  ) {
    const trList = element.trList!
    // 获取编辑器的基础配置
    const {
      scale,
      table: { defaultTrMinHeight }
    } = this.options
    const { isPagingMode, tdPaddingWidth, tdPaddingHeight } = option
    // 计算前移除上一次的高度
    for (let t = 0; t < trList.length; t++) {
      const tr = trList[t]
      tr.height = tr.minHeight || defaultTrMinHeight
      tr.minHeight = tr.height
    }
    // 计算表格行列
    this.tableParticle.computeRowColInfo(element)
    // 计算表格内元素信息
    for (let t = 0; t < trList.length; t++) {
      const tr = trList[t]
      for (let d = 0; d < tr.tdList.length; d++) {
        const td = tr.tdList[d]
        const rowList = this.computeRowList({
          innerWidth: (td.width! - tdPaddingWidth) * scale,
          elementList: td.value,
          isFromTable: true,
          isPagingMode
        })
        const rowHeight = rowList.reduce((pre, cur) => pre + cur.height, 0)
        td.rowList = rowList
        // 移除缩放导致的行高变化-渲染时会进行缩放调整
        const curTdHeight = rowHeight / scale + tdPaddingHeight
        // 内容高度大于当前单元格高度需增加
        if (td.height! < curTdHeight) {
          const extraHeight = curTdHeight - td.height!
          const changeTr = trList[t + td.rowspan - 1]
          changeTr.height += extraHeight
          changeTr.tdList.forEach(changeTd => {
            changeTd.height! += extraHeight
            if (!changeTd.realHeight) {
              changeTd.realHeight = changeTd.height!
            } else {
              changeTd.realHeight! += extraHeight
            }
          })
        }
        // 当前单元格最小高度及真实高度（包含跨列）
        let curTdMinHeight = 0
        let curTdRealHeight = 0
        let i = 0
        while (i < td.rowspan) {
          const curTr = trList[i + t] || trList[t]
          curTdMinHeight += curTr.minHeight!
          curTdRealHeight += curTr.height!
          i++
        }
        td.realMinHeight = curTdMinHeight
        td.realHeight = curTdRealHeight
        td.mainHeight = curTdHeight
      }
      // 设置当前行中td中最大的高度为当前行的高度
      // tr.height = Math.max(...tr.tdList.map(td => td.height!))
    }
    // 单元格高度大于实际内容高度需减少
    const reduceTrList = this.tableParticle.getTrListGroupByCol(trList)
    for (let t = 0; t < reduceTrList.length; t++) {
      const tr = reduceTrList[t]
      let reduceHeight = -1
      for (let d = 0; d < tr.tdList.length; d++) {
        const td = tr.tdList[d]
        const curTdRealHeight = td.realHeight!
        const curTdHeight = td.mainHeight!
        const curTdMinHeight = td.realMinHeight!
        // 获取最大可减少高度
        const curReduceHeight =
          curTdHeight < curTdMinHeight
            ? curTdRealHeight - curTdMinHeight
            : curTdRealHeight - curTdHeight
        if (!~reduceHeight || curReduceHeight < reduceHeight) {
          reduceHeight = curReduceHeight
        }
      }
      if (reduceHeight > 0) {
        const changeTr = trList[t]
        changeTr.height -= reduceHeight
        changeTr.tdList.forEach(changeTd => {
          changeTd.height! -= reduceHeight
          changeTd.realHeight! -= reduceHeight
        })
      }
    }

    if (!element.pagingId || element.pagingIndex === 0) {
      console.log('处理高度后element', deepClone(element))
    }

    // 需要重新计算表格内值
    this.tableParticle.computeRowColInfo(element)

    // 计算出表格高度
    const tableHeight = this.tableParticle.getTableHeight(element)
    const tableWidth = this.tableParticle.getTableWidth(element)

    return {
      tableHeight,
      tableWidth
    }
  }

