    normalizePastedColors(editor) {
      const isGrayLikeColor = (color) => {
        if (!color || typeof color !== "string") return false;

        const c = color.trim().toLowerCase();

        const rgbMatch = c.match(/^rgb\((\d+),\s*(\d+),\s*(\d+)\)$/);
        if (rgbMatch) {
          const [r, g, b] = rgbMatch.slice(1).map(Number);
          return (
            Math.abs(r - g) < 30 &&
            Math.abs(g - b) < 30 &&
            Math.abs(r - b) < 30
          );
        }

        const hexMatch = c.match(/^#([0-9a-f]{6})$/);
        if (hexMatch) {
          const hex = hexMatch[1];
          const r = parseInt(hex.slice(0, 2), 16);
          const g = parseInt(hex.slice(2, 4), 16);
          const b = parseInt(hex.slice(4, 6), 16);

          return (
            Math.abs(r - g) < 30 &&
            Math.abs(g - b) < 30 &&
            Math.abs(r - b) < 30
          );
        }

        return false;
      };
      const value = editor.command.getValue();
      let changed = false;

      const normalizeItemColor = (item) => {
