```
onInsertCustomTable () {
      const table = {
        value: '',
        type: 'table',
        trList: [
        ],
        width: 558,
        height: 42,
        colgroup: []
      }

      // colgroup
      const colgroup = []
      const colNum = 6
      for (let i = 0; i < colNum; i++) {
        colgroup.push({
          width: 558 / colNum
        })
      }
      table.colgroup = colgroup

      // trList
      const rowNum = 100
      for (let i = 0; i < rowNum; i++) {
        const trList = {
          height: 42,
          tdList: []
        }
        for (let j = 0; j < colNum; j++) {
          const td = {
            colspan: 1,
            rowspan: 1,
            value: `${i + 1}-${j + 1}`
          }
          trList.tdList.push(this.getCell(td))
        }
        table.trList.push(trList)
      }

      // insert table
      this.$refs.CanvasEditor.instance.command.executeAppendElementList([table])
    }
